  const alpha = /rgba?\(.*[,/]\s*([\d.]+)\)$/.exec(fogStyle.background)?.[1];
  // 23a «без скла»: туман — густіший серпанок (як колишній запасний варіант без розмиття), жодного backdrop-filter.
