  await expectNoSideScroll(host, 'p12e-host-reveal');
  await shot(stage, 'p12e-stage-reveal');

  // 7. Штраф на виході з розкриття: Оля 0, Іра 200; рядок «(вихід із гри)» в аркуші.
  await click(host, 'Далі');
